'use strict';

const VAT_RATES = { food: 10, books: 0, general: 20 };

function roundHalfAwayFromZero(x) {
  return Math.sign(x) * Math.round(Math.abs(x));
}

/** Returns `percent`% of `cents`, rounded half away from zero. */
function percentOf(cents, percent) {
  return roundHalfAwayFromZero((cents * percent) / 100);
}

/**
 * Formats cents as a string such as "€12.05" or "-€0.40".
 */
function format(cents) {
  const sign = cents < 0 ? '-' : '';
  const a = Math.abs(cents);
  return `${sign}€${Math.floor(a / 100)}.${String(a % 100).padStart(2, '0')}`;
}

/**
 * Splits `totalCents` across `weights` proportionally so that the parts sum exactly to totalCents.
 * Uses the largest-remainder method (SPEC section 2.3).
 */
function allocate(totalCents, weights) {
  const sum = weights.reduce((a, b) => a + b, 0);
  if (sum === 0) return weights.map(() => 0);
  const parts = weights.map((w) => Math.floor((totalCents * w) / sum));
  let remainder = totalCents - parts.reduce((a, b) => a + b, 0);
  // Distribute the remaining cents to the parts with the largest fractional remainders,
  // breaking ties in favour of earlier indices.
  const indexed = weights.map((w, i) => {
    const num = totalCents * w;
    return { i, remainder: num % sum };
  });
  indexed.sort((a, b) => {
    if (b.remainder !== a.remainder) return b.remainder - a.remainder;
    return a.i - b.i;
  });
  for (let i = 0; i < remainder; i++) {
    parts[indexed[i].i]++;
  }
  return parts;
}

/**
 * CouponError — thrown when a coupon is invalid.
 */
class CouponError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CouponError';
  }
}

function assertCouponUsable(coupon, { date, subtotalCents, customerId, usedBy }) {
  if (coupon.validFrom && date < coupon.validFrom) throw new CouponError(`Coupon ${coupon.code} is not valid yet`);
  if (coupon.validTo && date >= coupon.validTo) throw new CouponError(`Coupon ${coupon.code} has expired`);
  if (coupon.minSubtotalCents && subtotalCents < coupon.minSubtotalCents) {
    throw new CouponError(`Coupon ${coupon.code} requires a subtotal of at least ${coupon.minSubtotalCents} cents`);
  }
  if (usedBy.has(`${customerId}:${coupon.code}`)) throw new CouponError(`Coupon ${coupon.code} was already used by ${customerId}`);
}

function appliesTo(coupon, category) {
  return !coupon.categories || coupon.categories.includes(category);
}

/**
 * Prices order lines (SPEC section 5 and 6).
 * @param lines   [{ sku, qty }] (already merged, validated)
 * @param catalog Catalog
 * @param coupon  coupon object or null
 * @returns [{ sku, qty, category, unitPriceCents, grossCents, discountCents, netCents, vatRate, taxCents, totalCents }]
 */
function priceLines(lines, catalog, coupon) {
  const priced = lines.map(({ sku, qty }) => {
    const p = catalog.get(sku);
    const grossCents = p.priceCents * qty;
    return { sku, qty, category: p.category, unitPriceCents: p.priceCents, grossCents, discountCents: 0, vatRate: VAT_RATES[p.category] };
  });

  if (coupon) {
    if (coupon.type === 'PERCENT') {
      for (const l of priced) {
        if (!appliesTo(coupon, l.category)) continue;
        l.discountCents = percentOf(l.grossCents, coupon.percent);
      }
    } else if (coupon.type === 'FIXED') {
      const subtotal = priced.reduce((a, l) => a + l.grossCents, 0);
      const amount = Math.min(coupon.amountCents, subtotal);
      const parts = allocate(amount, priced.map((l) => l.grossCents));
      priced.forEach((l, i) => { l.discountCents = parts[i]; });
    } else if (coupon.type === 'BOGO') {
      for (const l of priced) {
        if (l.sku !== coupon.sku) continue;
        const freeUnits = Math.floor(l.qty / (coupon.buy + coupon.free)) * coupon.free;
        l.discountCents = freeUnits * l.unitPriceCents;
      }
    } else {
      throw new CouponError(`Unknown coupon type: ${coupon.type}`);
    }
  }

  for (const l of priced) {
    l.netCents = l.grossCents - l.discountCents;
    l.taxCents = percentOf(l.netCents, l.vatRate);
    l.totalCents = l.netCents + l.taxCents;
  }
  return priced;
}

function summarize(priced) {
  const sum = (k) => priced.reduce((a, l) => a + l[k], 0);
  return {
    subtotalCents: sum('grossCents'),
    discountCents: sum('discountCents'),
    netCents: sum('netCents'),
    taxCents: sum('taxCents'),
    totalCents: sum('totalCents'),
  };
}

module.exports = { VAT_RATES, CouponError, assertCouponUsable, priceLines, summarize };

'use strict';

const { CouponError, assertCouponUsable, priceLines, summarize } = require('./pricing');
const { InventoryError } = require('./inventory');

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

class OrderError extends Error {
  constructor(message) {
    super(message);
    this.name = 'OrderError';
  }
}

class RefundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'RefundError';
  }
}

/** Order life cycle (SPEC section 7). */
class OrderService {
  constructor({ catalog, inventory, coupons = [] }) {
    this.catalog = catalog;
    this.inventory = inventory;
    this.coupons = new Map(coupons.map((c) => [c.code, c]));
    this.orders = new Map();
    this.nextOrderNo = 1;
    this.couponUsage = new Set(); // "customerId:CODE"
  }

  _mergeLines(lines) {
    if (!Array.isArray(lines) || lines.length === 0) throw new OrderError('An order needs at least one line');
    const merged = new Map();
    for (const { sku, qty } of lines) {
      if (!Number.isInteger(qty) || qty <= 0) throw new OrderError(`Invalid quantity for ${sku}: ${qty}`);
      if (!this.catalog.has(sku)) throw new OrderError(`Unknown SKU: ${sku}`);
      if (!this.catalog.get(sku).active) throw new OrderError(`Product ${sku} is not available`);
      merged.set(sku, (merged.get(sku) ?? 0) + qty);
    }
    return [...merged].map(([sku, qty]) => ({ sku, qty }));
  }

  createOrder({ customerId, lines, couponCode = null, date }) {
    if (typeof customerId !== 'string' || customerId === '') throw new OrderError('customerId is required');
    if (typeof date !== 'string' || !DATE_RE.test(date)) throw new OrderError('date must be YYYY-MM-DD');
    const merged = this._mergeLines(lines);

    let coupon = null;
    if (couponCode !== null) {
      coupon = this.coupons.get(couponCode);
      if (!coupon) throw new CouponError(`Unknown coupon: ${couponCode}`);
      const subtotalCents = merged.reduce((a, l) => a + this.catalog.get(l.sku).priceCents * l.qty, 0);
      assertCouponUsable(coupon, { date, subtotalCents, customerId, usedBy: this.couponUsage });
    }

    // All-or-nothing stock reservation (SPEC 7.4)
    for (const l of merged) this.inventory.reserve(l.sku, l.qty);

    const priced = priceLines(merged, this.catalog, coupon);
    const id = `O${String(this.nextOrderNo++).padStart(4, '0')}`;
    const order = { id, customerId, date, couponCode, status: 'placed', lines: priced, totals: summarize(priced) };
    if (coupon) this.couponUsage.add(`${customerId}:${coupon.code}`);
    this.orders.set(id, order);
    return order;
  }

  getOrder(id) {
    const o = this.orders.get(id);
    if (!o) throw new OrderError(`Unknown order: ${id}`);
    return o;
  }

  cancelOrder(id) {
    const o = this.getOrder(id);
    if (o.status !== 'placed') throw new OrderError(`Order ${id} cannot be cancelled in status ${o.status}`);
    for (const l of o.lines) this.inventory.release(l.sku, l.qty);
    o.status = 'cancelled';
    if (o.couponCode) this.couponUsage.delete(`${o.customerId}:${o.couponCode}`);
    return o;
  }

  listOrders() {
    return [...this.orders.values()];
  }

  refundOrder(orderId, items, { date, restock = true } = {}) {
    const order = this.getOrder(orderId);
    if (order.status !== 'placed' && order.status !== 'partially_refunded') {
      throw new RefundError(`Cannot refund order ${orderId}: status is ${order.status}`);
    }

    // Validate date
    if (typeof date !== 'string' || !DATE_RE.test(date)) {
      throw new RefundError('refund date must be YYYY-MM-DD');
    }
    const orderDate = order.date;
    if (date < orderDate) {
      throw new RefundError('refund date cannot be earlier than the order date');
    }

    // Validate items: non-empty array, positive integer quantities
    if (!Array.isArray(items) || items.length === 0) {
      throw new RefundError('items must be a non-empty array');
    }
    for (const it of items) {
      if (!Number.isInteger(it.qty) || it.qty <= 0) {
        throw new RefundError('each item qty must be a positive integer');
      }
    }

    // Merge items with same SKU
    const merged = new Map();
    for (const it of items) {
      if (!merged.has(it.sku)) merged.set(it.sku, 0);
      merged.get(it.sku) += it.qty;
    }

    // Validate each SKU is a line of the order
    const orderLineSkus = new Set(order.lines.map(l => l.sku));
    for (const sku of merged.keys()) {
      if (!orderLineSkus.has(sku)) {
        throw new RefundError(`SKU ${sku} is not a line of the order`);
      }
    }

    // Validate refunded quantities
    for (const l of order.lines) {
      const qty = merged.get(l.sku) || 0;
      if (qty > l.qty - (l.refundedQty || 0)) {
        throw new RefundError(`Refunded quantity exceeds available units for ${l.sku}`);
      }
    }

    // Compute refund amounts per line
    const refundRecords = [];
    let refundNet = 0;
    let refundTax = 0;

    for (const l of order.lines) {
      const qty = merged.get(l.sku);
      if (!qty) continue;
      const line = { sku: l.sku, qty: qty, netCents: l.netCents, taxCents: l.taxCents, totalCents: l.totalCents };
      let refundedNet, refundedTax;

      if (l.qty - qty === 0) {
        // All units refunded — refund the full line
        refundedNet = l.netCents;
        refundedTax = l.taxCents;
      } else {
        refundedNet = roundHalfAwayFromZero(l.netCents * qty / l.qty);
        refundedTax = roundHalfAwayFromZero(l.taxCents * qty / l.qty);
      }

      line.refundedQty = qty;
      line.refundedNetCents = refundedNet;
      line.refundedTaxCents = refundedTax;
      refundRecords.push(line);
      refundNet += refundedNet;
      refundTax += refundedTax;
    }

    // Apply refunds: restock if requested
    if (restock) {
      for (const l of order.lines) {
        const qty = merged.get(l.sku);
        if (qty) this.inventory.release(l.sku, qty);
      }
    }

    // Determine status: fully refunded → 'refunded', otherwise 'partially_refunded'
    const allRefunded = refundRecords.every(r => r.refundedQty === r.qty);
    if (allRefunded) {
      order.status = 'refunded';
    } else {
      order.status = 'partially_refunded';
    }

    const refundRecord = {
      id: `R${String(this.nextOrderNo++).padStart(4, '0')}`,
      orderId: orderId,
      date,
      lines: refundRecords,
      totalCents: refundNet + refundTax,
    };

    order.refunds = order.refunds || [];
    order.refunds.push(refundRecord);

    return refundRecord;
  }
}

module.exports = { OrderService, OrderError, RefundError };

